/**
 * Crypto Node - Version 2
 * Provide cryptographic utilities
 */


export interface CryptoV2Params {
  action?: 'decrypt' | 'encrypt' | 'generate' | 'hash' | 'hmac' | 'sign' | Expression<string>;
/**
 * Whether the data to hashed should be taken from binary field
 * @displayOptions.show { action: ["hash", "hmac"] }
 * @default false
 */
    binaryData?: boolean | Expression<boolean>;
/**
 * Name of the binary property which contains the input data
 * @displayOptions.show { action: ["hash", "hmac"], binaryData: [true] }
 * @default data
 */
    binaryPropertyName?: string | Expression<string>;
/**
 * The hash type to use
 * @displayOptions.show { action: ["hash"] }
 * @default SHA256
 */
    type?: 'MD5' | 'SHA1' | 'SHA256' | 'SHA3-256' | 'SHA3-384' | 'SHA3-512' | 'SHA384' | 'SHA512' | Expression<string>;
/**
 * The value that should be hashed
 * @displayOptions.show { action: ["hash"], binaryData: [false] }
 * @required when the displayOptions conditions above match
 */
    value?: string | Expression<string>;
/**
 * Name of the property to which to write the hash
 * @displayOptions.show { action: ["hash"] }
 * @default data
 */
    dataPropertyName?: string | Expression<string>;
/**
 * Encoding
 * @displayOptions.show { action: ["hash"] }
 * @default hex
 */
    encoding?: 'base64' | 'hex' | Expression<string>;
/**
 * Choose from the list, or specify an ID using an &lt;a href="https://docs.n8n.io/code/expressions/"&gt;expression&lt;/a&gt;
 * @displayOptions.show { action: ["sign"] }
 * @required when the displayOptions conditions above match
 */
    algorithm?: 'RSA-MD5' | 'RSA-RIPEMD160' | 'RSA-SHA1' | 'RSA-SHA1-2' | 'RSA-SHA224' | 'RSA-SHA256' | 'RSA-SHA3-224' | 'RSA-SHA3-256' | 'RSA-SHA3-384' | 'RSA-SHA3-512' | 'RSA-SHA384' | 'RSA-SHA512' | 'RSA-SHA512/224' | 'RSA-SHA512/256' | 'RSA-SM3' | 'blake2b-512' | 'blake2b512' | 'blake2s-256' | 'blake2s256' | 'id-rsassa-pkcs1-v1_5-with-sha3-224' | 'id-rsassa-pkcs1-v1_5-with-sha3-256' | 'id-rsassa-pkcs1-v1_5-with-sha3-384' | 'id-rsassa-pkcs1-v1_5-with-sha3-512' | 'keccak-224' | 'keccak-256' | 'keccak-384' | 'keccak-512' | 'keccak-kmac-128' | 'keccak-kmac-256' | 'keccak-kmac128' | 'keccak-kmac256' | 'md5' | 'md5-sha1' | 'md5WithRSAEncryption' | 'ripemd' | 'ripemd-160' | 'ripemd160' | 'ripemd160WithRSA' | 'rmd160' | 'sha-1' | 'sha-224' | 'sha-256' | 'sha-256/192' | 'sha-384' | 'sha-512' | 'sha-512/224' | 'sha-512/256' | 'sha1' | 'sha1WithRSAEncryption' | 'sha2-224' | 'sha2-256' | 'sha2-256/192' | 'sha2-384' | 'sha2-512' | 'sha2-512/224' | 'sha2-512/256' | 'sha224' | 'sha224WithRSAEncryption' | 'sha256' | 'sha256-192' | 'sha256WithRSAEncryption' | 'sha3-224' | 'sha3-256' | 'sha3-384' | 'sha3-512' | 'sha384' | 'sha384WithRSAEncryption' | 'sha512' | 'sha512-224' | 'sha512-224WithRSAEncryption' | 'sha512-256' | 'sha512-256WithRSAEncryption' | 'sha512WithRSAEncryption' | 'shake-128' | 'shake-256' | 'shake128' | 'shake256' | 'sm3' | 'sm3WithRSAEncryption' | 'ssl3-md5' | 'ssl3-sha1' | Expression<string>;
/**
 * Encoding that will be used to generate string
 * @displayOptions.show { action: ["generate"] }
 * @default uuid
 */
    encodingType?: 'ascii' | 'base64' | 'hex' | 'uuid' | Expression<string>;
/**
 * Length of the generated string
 * @displayOptions.show { action: ["generate"], encodingType: ["ascii", "base64", "hex"] }
 * @default 32
 */
    stringLength?: number | Expression<number>;
/**
 * Mode
 * @displayOptions.show { action: ["encrypt", "decrypt"] }
 * @default symmetric
 */
    mode?: 'symmetric' | 'asymmetric' | Expression<string>;
/**
 * Authenticated cipher to use. The same value must be selected on encrypt and decrypt.
 * @displayOptions.show { action: ["encrypt", "decrypt"], mode: ["symmetric"] }
 * @default aes-256-gcm
 */
    cipher?: 'aes-256-gcm' | 'aes-192-gcm' | 'aes-128-gcm' | 'chacha20-poly1305' | Expression<string>;
/**
 * Hash algorithm for RSA-OAEP. Select the same value for encryption and decryption.
 * @displayOptions.show { action: ["encrypt", "decrypt"], mode: ["asymmetric"] }
 * @default sha256
 */
    oaepHash?: 'sha256' | 'sha1' | Expression<string>;
}

export interface CryptoV2Credentials {
  crypto: CredentialReference;
}

interface CryptoV2NodeBase {
  type: 'n8n-nodes-base.crypto';
  version: 2;
}

export type CryptoV2ParamsNode = CryptoV2NodeBase & {
  config: NodeConfig<CryptoV2Params> & { credentials?: CryptoV2Credentials };
};

export type CryptoV2Node = CryptoV2ParamsNode;